// single List is strictly cheaper than the agent's existing steady-state
// profile — the same argument list_resources' own doc comment makes for its
// per-namespace list.
//
// "Available" is deliberately conservative about protocol: Kubernetes tracks
// nodePort allocation per (port, protocol) pair, so in principle 30500/TCP
// and 30500/UDP could be allocated independently — but this reports a port
// unavailable if ANY protocol currently holds it, rather than asking the
// caller to reason about a distinction the catalogue fault this tool exists
// for (a plain TCP Service conflict) never needed. A caller proposing a
// replacement port wants one that is unambiguously free, not one that is
// free only for a protocol nobody asked about.
func (e *ToolExecutor) listNodePortAllocations(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args listNodePortAllocationsArgs
	if len(rawArgs) > 0 {
		if err := json.Unmarshal(rawArgs, &args); err != nil {
			return nil, false, fmt.Errorf("invalid args: %w", err)
		}
	}
	if args.Port < 0 || args.Port > 65535 {
		return nil, false, fmt.Errorf("port %d is out of range", args.Port)
	}

	list, err := e.typed.CoreV1().Services(metav1.NamespaceAll).List(ctx, metav1.ListOptions{})
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}

	var allocations []nodePortAllocation
	for _, svc := range list.Items {
		for _, p := range svc.Spec.Ports {
			if p.NodePort == 0 {
				continue
			}
			if args.Port != 0 && p.NodePort != args.Port {
				continue
			}
			allocations = append(allocations, nodePortAllocation{
				Port:        p.NodePort,
				Protocol:    string(p.Protocol),
				Namespace:   svc.Namespace,
				Service:     svc.Name,
				ServicePort: p.Name,
			})
		}
	}

	// Deterministic ordering for the same reason list_resources sorts
	// before windowing: API server list order is not a contract, and an
	// unstable order would make two identical calls against an unchanged
	// cluster look like churn that never happened.
	sort.Slice(allocations, func(i, j int) bool {
		if allocations[i].Port != allocations[j].Port {
			return allocations[i].Port < allocations[j].Port
		}
		if allocations[i].Namespace != allocations[j].Namespace {
			return allocations[i].Namespace < allocations[j].Namespace
		}
		return allocations[i].Service < allocations[j].Service
	})

	total := len(allocations)
	truncated := false
	// Windowing only applies to the survey shape — a targeted port check
	// never has enough matches (in practice 0 or 1, occasionally 2 across
	// protocols) to need a limit, and applying one anyway would just be
	// dead code on a path that can never exercise it.
	if args.Port == 0 {
		limit := args.Limit
		if limit <= 0 {
			limit = defaultNodePortListLimit
		}
		if limit > maxNodePortListLimit {
			limit = maxNodePortListLimit
		}
		if total > limit {
			allocations = allocations[:limit]
			truncated = true
		}
	}

	result := listNodePortAllocationsResult{
		Allocations:  allocations,
		Returned:     len(allocations),
		TotalMatched: total,
		Truncated:    truncated,
	}
	if args.Port != 0 {
		port := args.Port
		available := total == 0
		result.Port = &port
		result.Available = &available
	}
	return mustMarshal(result), truncated, nil
}
